SELECT * FROM schedules 
WHERE user_id = #{userId} AND schedule_date = #{scheduleDate}
ORDER BY activity_time ASC

SELECT * FROM schedules 
WHERE user_id = #{userId}
ORDER BY schedule_date ASC, activity_time ASC

SELECT * FROM schedules 
WHERE user_id = #{userId} 
AND schedule_date BETWEEN #{startDate} AND #{endDate}
ORDER BY schedule_date ASC, activity_time ASC
